import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, timestamp, id)
    sell_heap = []  # entries: (price, timestamp, id)
    orders_info = {}  # id -> {'side':, 'price':, 'qty':, 'active':}

    def match_incoming(incoming_id, side, price, qty, is_market):
        local_trades = []
        opposite_heap = sell_heap if side == 'buy' else buy_heap
        while qty > 0 and opposite_heap:
            top = opposite_heap[0]
            if side == 'buy':
                top_price = top[0]
            else:
                top_price = -top[0]
            rest_id = top[2]
            info = orders_info.get(rest_id)
            if info is None or not info['active']:
                heapq.heappop(opposite_heap)
                continue
            if not is_market:
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break
            trade_qty = min(qty, info['qty'])
            if side == 'buy':
                local_trades.append([incoming_id, rest_id, top_price, trade_qty])
            else:
                local_trades.append([rest_id, incoming_id, top_price, trade_qty])
            qty -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(opposite_heap)
            # else the top order stays with reduced qty; since incoming qty
            # must now be 0 (as trade_qty = min(qty, info['qty'])), loop ends
        return qty, local_trades

    for idx, order in enumerate(orders):
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining_qty, new_trades = match_incoming(oid, side, price, qty, False)
            trades.extend(new_trades)
            if remaining_qty > 0:
                info = {'side': side, 'price': price, 'qty': remaining_qty, 'active': True}
                orders_info[oid] = info
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, idx, oid))
                else:
                    heapq.heappush(sell_heap, (price, idx, oid))
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining_qty, new_trades = match_incoming(oid, side, price, qty, False)
            trades.extend(new_trades)
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining_qty, new_trades = match_incoming(oid, side, None, qty, True)
            trades.extend(new_trades)
            orders_info[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False}

    return trades

